parameters.jsCode:
const req = $json.body || $json;
const phone = String(req.phone || '').replace(/\D/g, '');
const payload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: phone
};
if (req.template_name) {
  const lang = req.template_language || req.languageCode || 'en_IN';
  payload.type = 'template';
  payload.template = {
    name: req.template_name,
    language: { code: lang },
    components: (req.template_params && req.template_params.length > 0) ? [{
      type: 'body',
      parameters: (req.template_params || []).map(t => ({ type: 'text', text: String(t) }))
    }] : []
  };
} else {
  const body = String(req.message || '').trim();
  if (!body) throw new Error('Cannot send empty WhatsApp message. Provide a message or template_name.');
  payload.type = 'text';
  payload.text = { preview_url: false, body };
}
return [{
  json: {
    payload,
    lead_id: req.lead_id,
    raw_phone: req.phone,
    message_text: req.message || null,
    template_name: req.template_name || null
  }
}];

